/* Devolve o cartão com os ajustes (um objeto novo; o original não muda). */
function aplicarAjustes(c) {
  const f = CATALOGO_AJUSTES.campos[c.id], t = CATALOGO_AJUSTES.tags[c.id];
  if (!f && !t) return c;
  const out = {...c, ...f};
  delete out.nivel; delete out.registro;
  if (f && f.registro) out.tags = out.tags.replace(/Register::\S+/, "Register::" + f.registro);
  if (f && f.nivel) out.tags = out.tags.replace(/Niveau::\S+/, "Niveau::" + f.nivel);
  if (t) out.tags += " " + t;
  return out;
}
